from qiskit import QuantumCircuit
from qiskit.circuit.library import HGate, CPhaseGate, SwapGate

qc = QuantumCircuit(5)

# Apply Hadamard gates to all qubits
for qubit in range(5):
    qc.append(HGate(), [qubit])

# Apply controlled-phase gates between pairs of qubits
for qubit1 in range(4):
    for qubit2 in range(qubit1 + 1, 5):
        qc.append(CPhaseGate(1.0), [qubit1, qubit2])

# Apply SWAP gates between pairs of qubits
for qubit1 in range(4):
    for qubit2 in range(qubit1 + 1, 5):
        qc.append(SwapGate(), [qubit1, qubit2])

# Apply another set of SWAP gates to reverse the order
for qubit1 in range(4):
    for qubit2 in range(qubit1 + 1, 5):
        qc.append(SwapGate(), [qubit1, qubit2])

# Apply another set of controlled-phase gates
for qubit1 in range(4):
    for qubit2 in range(qubit1 + 1, 5):
        qc.append(CPhaseGate(1.0), [qubit1, qubit2])

# Apply another set of Hadamard gates
for qubit in range(5):
    qc.append(HGate(), [qubit])

